/**
 * A changed value or text, shown as old and new (`design/components/diff.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/diff.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, type JSX } from 'solid-js'

import {
  Each,
  claimSlot,
  createCell,
  createDerived,
  devWarning,
  diffLines,
  diffRuns,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/diff.module.css'
import Button from '../controls/Button'

export interface DiffMessages {
  /** Read before the old value of a value that changed: "from". */
  from: string
  /** Read between the old value and the new one: "to". */
  to: string
  /** Read before a value, or a line, that only the new side has. */
  added: string
  /** Read before a value, or a line, that only the old side has. */
  removed: string
  /** A collapsed run's Button. */
  unchanged: (count: number) => string
}

export interface DiffProps {
  /**
   * The new value. Missing, `null` or empty means there is none: with a `before`, the change is
   * a removal. Equal sides are no change.
   */
  after?: string | null
  /**
   * The old value. Missing, `null` or empty means there was none: with an `after`, the change is
   * an addition.
   */
  before?: string | null
  /**
   * In `lines`, the unchanged lines kept beside each change. The unchanged lines past them are
   * one row that says how many it holds and shows them when pressed. `Infinity` keeps every
   * line.
   */
  context?: number
  /**
   * `inline` (the default) is a short value inside a sentence or a cell. `lines` compares two
   * texts of several lines, line by line.
   */
  display?: 'inline' | 'lines'
  /**
   * Names the `lines` form, which is a region. The `lines` form needs it; `inline` does not use
   * it.
   */
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: DiffMessages
}

/** A changed value or text, shown as old and new. */
export default function Diff(given: DiffProps): JSX.Element {
  const props = mergeProps(
    {
      display: 'inline',
      context: 3,
      messages: (() => ({
        from: 'from',
        to: 'to',
        added: 'added',
        removed: 'removed',
        unchanged: (count: number) => `${count} unchanged ${count === 1 ? 'line' : 'lines'}`,
      }))(),
    } as Defaults<DiffProps, 'display' | 'context' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const opened = createCell([] as number[])
    const old = createDerived(() => props.before ?? '')
    const next = createDerived(() => props.after ?? '')
    const runs = createDerived(() =>
      props.display === 'lines' ? diffRuns(diffLines(old.value, next.value), props.context) : [],
    )
    const effect1 = () => {
      devWarning(
        props.display === 'lines' && props.label === undefined,
        'Diff: the `lines` form is a region, and a region needs a name; pass `label`.',
      )
    }
    watchEffect(
      createMemo(() => props.display === 'lines' && props.label === undefined),
      effect1,
      true,
    )
    return (
      <>
        {old.value !== '' || next.value !== '' ? (
          props.display === 'lines' ? (
            <section class={styles.lines} aria-label={props.label} data-member="diff">
              {/* rows */}
              <ol class={styles.rows} role="list">
                <Each of={runs.value} by={(piece) => piece.key} renew>
                  {(piece) => (
                    <>
                      {piece.collapsed ? (
                        <li class={styles.run}>
                          <div class={styles.fold}>
                            <Button
                              variant="ghost"
                              tone="neutral"
                              size="sm"
                              icon={opened.value.includes(piece.key) ? 'collapse' : 'expand'}
                              label={props.messages.unchanged(piece.rows.length)}
                              expanded={opened.value.includes(piece.key)}
                              aria-controls={
                                opened.value.includes(piece.key)
                                  ? `${uid}-run-${piece.key}`
                                  : undefined
                              }
                              onClick={() =>
                                (opened.value = opened.value.includes(piece.key)
                                  ? opened.value.filter((key) => key !== piece.key)
                                  : [...opened.value, piece.key])
                              }
                            />
                          </div>
                          {opened.value.includes(piece.key) ? (
                            <ol class={styles.rows} id={`${uid}-run-${piece.key}`} role="list">
                              <Each
                                of={piece.rows}
                                by={(row) =>
                                  row.kind === 'removed'
                                    ? `r${row.beforeLine}`
                                    : `${row.kind === 'added' ? 'a' : 's'}${row.afterLine}`
                                }
                                renew
                              >
                                {(row) => (
                                  <li
                                    class={styles.row}
                                    data-kind={row.kind === 'same' ? undefined : row.kind}
                                  >
                                    {/* marker */}
                                    <span class={styles.marker} aria-hidden="true">
                                      {row.kind === 'added'
                                        ? '+'
                                        : row.kind === 'removed'
                                          ? '−'
                                          : ''}
                                    </span>
                                    {row.kind !== 'same' ? (
                                      <span class={styles.spoken}>
                                        {(row.kind === 'added'
                                          ? props.messages.added
                                          : props.messages.removed) + ' '}
                                      </span>
                                    ) : null}
                                    {/* text */}
                                    <span class={styles.text}>{row.text}</span>
                                  </li>
                                )}
                              </Each>
                            </ol>
                          ) : null}
                        </li>
                      ) : (
                        <Each
                          of={piece.rows}
                          by={(row) =>
                            row.kind === 'removed'
                              ? `r${row.beforeLine}`
                              : `${row.kind === 'added' ? 'a' : 's'}${row.afterLine}`
                          }
                          renew
                        >
                          {(row) => (
                            <li
                              class={styles.row}
                              data-kind={row.kind === 'same' ? undefined : row.kind}
                            >
                              {/* marker */}
                              <span class={styles.marker} aria-hidden="true">
                                {row.kind === 'added' ? '+' : row.kind === 'removed' ? '−' : ''}
                              </span>
                              {row.kind !== 'same' ? (
                                <span class={styles.spoken}>
                                  {(row.kind === 'added'
                                    ? props.messages.added
                                    : props.messages.removed) + ' '}
                                </span>
                              ) : null}
                              {/* text */}
                              <span class={styles.text}>{row.text}</span>
                            </li>
                          )}
                        </Each>
                      )}
                    </>
                  )}
                </Each>
              </ol>
            </section>
          ) : old.value === next.value ? (
            <span class={styles.inline} data-member="diff">
              {next.value}
            </span>
          ) : old.value === '' ? (
            <span class={styles.inline} data-member="diff">
              <span class={styles.spoken}>{props.messages.added + ' '}</span>
              {/* sign */}
              <span class={styles.sign} aria-hidden="true">
                {'+'}
              </span>
              {/* after */}
              <ins class={styles.after}>{next.value}</ins>
            </span>
          ) : next.value === '' ? (
            <span class={styles.inline} data-member="diff">
              <span class={styles.spoken}>{props.messages.removed + ' '}</span>
              {/* before */}
              <del class={styles.before}>{old.value}</del>
            </span>
          ) : (
            <span class={styles.inline} data-member="diff">
              <span class={styles.spoken}>{props.messages.from + ' '}</span>
              {/* before */}
              <del class={styles.before}>{old.value}</del>
              {/* arrow */}
              <span class={styles.arrow} aria-hidden="true">
                {'→'}
              </span>
              <span class={styles.spoken}>{' ' + props.messages.to + ' '}</span>
              {/* after */}
              <ins class={styles.after}>{next.value}</ins>
            </span>
          )
        ) : null}
      </>
    )
  })
}
